def evaluate(current_reputation, observation, my_history, round_num):
    donor = observation['donor']
    recipient = observation['recipient']
    action = observation['action']  # 'donate' or 'not_donate'
    # Ensure both agents are in our reputation dictionary
    if donor not in reps:
        reps[donor] = 0.0
    if recipient not in reps:
        reps[recipient] = 0.0
    recipient_rep = reps[recipient]
    # Update donor's reputation based on action and recipient's reputation
    if action == 'donate':
        if recipient_rep >= 0:
            new_rep = min(1.0, current_reputation + 0.1)
        else:
            new_rep = current_reputation
    else:  # did not donate
        if recipient_rep > -0.5:
            new_rep = max(-1.0, current_reputation - 0.1)
        else:
            new_rep = current_reputation
    reps[donor] = new_rep
    return new_rep

def decide(recipient_reputation, round_num, my_history):
    # Compute recent donation frequency (last 10 rounds)
    if len(my_history) == 0:
        donation_rate = 0.0
    else:
        recent = my_history[-10:]
        donation_rate = sum(recent) / len(recent)
    # Dynamic threshold: more forgiving when we donate less, stricter when we donate a lot
    threshold = 0.3 + 0.2 * donation_rate
    threshold += 0.01 * round_num      # gradually become more selective over time
    threshold = min(threshold, 0.9)    # cap to avoid extreme stinginess
    return recipient_reputation > threshold

